package com.example.eac_backend_project.transport;
import org.springframework.stereotype.Service;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.transaction.annotation.Transactional;
import com.example.eac_backend_project.repository.transport.*;
import com.example.eac_backend_project.Service.transport.*;
import java.time.*;
import java.math.*;
import java.util.*;
import static com.example.eac_backend_project.transport.TransportValues.*;

@Service @Transactional(readOnly=true)
public class TransportDashboardService {
 @Autowired TransportAccess access;
 @Autowired TransportCoreService core;
 @Autowired VehicleRepository vehicles;
 @Autowired DriverService drivers;
 @Autowired FuelService fuel;
 @Autowired MaintenanceService maintenance;
 @Autowired TransportVehicleProfiles profiles;
 @Autowired TransportWorkflows workflows;
 @Autowired TransportProcurementService procurement;
 @Autowired TransportPartReceipts receipts;
 @Autowired TransportDriverProfiles driverProfiles;
 public Map<String,Object> dashboard(){access.requireEntry();var fleet=access.visible(vehicles.findAll().stream().filter(v->v.getArchivedAt()==null).toList());var fuelEntries=fuel.getAllFuelEntries();var maintenanceEntries=maintenance.getAllMaintenanceEntries();var faults=workflows.faults(null);var orders=workflows.workOrders(null);var components=workflows.components(null);var documents=core.documents(null,false);var purchases=procurement.list(null);var user=access.current();LocalDate today=today();YearMonth month=YearMonth.from(today);
  Map<String,Long> availability=new TreeMap<>();long unassigned=0;for(var v:fleet){var profile=profiles.findByVehicle_Id(v.getId());String state=profile.map(p->p.operationalStatus).orElse(v.getStatus());availability.merge(state,1L,Long::sum);if(profile.map(p->p.driver==null).orElse(v.getAssignedDriver()==null||v.getAssignedDriver().isBlank()))unassigned++;}
  long active=availability.getOrDefault("AVAILABLE",0L)+availability.getOrDefault("ASSIGNED",0L);long openFaults=faults.stream().filter(f->!Set.of("CLOSED","REJECTED").contains(f.get("status"))).count();long pending=orders.stream().filter(o->!Set.of("COMPLETED","CANCELLED").contains(o.get("status"))).count();long overdue=components.stream().filter(c->"OVERDUE".equals(forecast(c).get("status"))).count();long expiring=documents.stream().filter(d->"EXPIRING_SOON".equals(d.get("status"))).count();long pendingPurchases=purchases.stream().filter(p->!Set.of("RECEIVED","REJECTED","CANCELLED").contains(p.get("status"))).count();BigDecimal monthFuel=fuelEntries.stream().filter(f->f.getDate()!=null&&YearMonth.from(f.getDate()).equals(month)).map(f->money(decimal(f.getCost()))).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal monthMaintenance=maintenanceEntries.stream().filter(m->m.getDate()!=null&&YearMonth.from(m.getDate()).equals(month)).map(m->money(decimal(m.getCost()))).reduce(BigDecimal.ZERO,BigDecimal::add);
  List<Map<String,Object>> metrics=List.of(metric("Total vehicles",fleet.size(),"/vehicles"),metric("Active vehicles",active,"/vehicles?state=active"),metric("Under maintenance",availability.getOrDefault("UNDER_MAINTENANCE",0L),"/vehicles?status=UNDER_MAINTENANCE"),metric("Out of service",availability.getOrDefault("OUT_OF_SERVICE",0L),"/vehicles?status=OUT_OF_SERVICE"),metric("Total drivers",drivers.getAllDriversEntries().size(),"/drivers"),metric("Unassigned vehicles",unassigned,"/vehicles?unassigned=true"),metric("Open fault reports",openFaults,"/transport/faults?open=true"),metric("Pending maintenance",pending,"/transport/work-orders?open=true"),metric("Overdue maintenance",overdue,"/transport/components?condition=OVERDUE"),metric("Expiring documents",expiring,"/transport/documents?status=EXPIRING_SOON"),metric("Pending procurement",pendingPurchases,"/transport/procurement?open=true"),moneyMetric("Monthly fuel cost",monthFuel,"/fuel?month="+month),moneyMetric("Monthly maintenance cost",monthMaintenance,"/maintenance?month="+month));
  List<Map<String,Object>> monthly=new ArrayList<>();for(int i=11;i>=0;i--){YearMonth period=month.minusMonths(i);BigDecimal fuelCost=fuelEntries.stream().filter(f->f.getDate()!=null&&YearMonth.from(f.getDate()).equals(period)).map(f->money(decimal(f.getCost()))).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal maintenanceCost=maintenanceEntries.stream().filter(m->m.getDate()!=null&&YearMonth.from(m.getDate()).equals(period)).map(m->money(decimal(m.getCost()))).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal purchasesCost=BigDecimal.ZERO;for(var p:purchases)for(var receipt:receipts.findByRequest_Id((Long)p.get("id")))if(receipt.receivedDate!=null&&YearMonth.from(receipt.receivedDate).equals(period))purchasesCost=purchasesCost.add(receipt.quantity.multiply(receipt.unitCost));long count=faults.stream().filter(f->f.get("createdAt") instanceof Instant instant&&YearMonth.from(instant.atZone(ZoneId.of("Africa/Accra"))).equals(period)).count();monthly.add(map("month",period.toString(),"fuel",fuelCost,"maintenance",maintenanceCost,"procurement",purchasesCost,"faults",count));}
  Map<String,Long> maintenanceTypes=new TreeMap<>(),maintenanceStates=new TreeMap<>();for(var m:maintenanceEntries)if(m.getMaintenanceType()!=null)maintenanceTypes.merge(m.getMaintenanceType().toUpperCase(Locale.ROOT),1L,Long::sum);for(var order:orders)maintenanceStates.merge(Objects.toString(order.get("status")),1L,Long::sum);
  var attention=fleet.stream().filter(v->profiles.findByVehicle_Id(v.getId()).map(p->Set.of("OUT_OF_SERVICE","UNDER_MAINTENANCE").contains(p.operationalStatus)).orElse(false)).map(v->map("title",v.getDvla()+" — "+v.getName(),"detail",profiles.findByVehicle_Id(v.getId()).map(p->p.operationalStatus).orElse(v.getStatus()),"path","/transport/vehicles/"+v.getId())).toList();
  List<Map<String,Object>> panels=List.of(map("title","Vehicles requiring attention","items",attention),map("title","Upcoming component maintenance","items",components.stream().filter(c->Set.of("OVERDUE","DUE","DUE_SOON","UPCOMING").contains(forecast(c).get("status"))).map(c->map("title",c.get("vehicle")+" — "+c.get("name"),"detail",forecast(c).get("status"),"path","/transport/components?record="+c.get("id"))).toList()),map("title","Expiring DVLA documents","items",documents.stream().filter(d->"DVLA".equals(d.get("documentType"))&&Set.of("EXPIRED","EXPIRING_SOON").contains(d.get("status"))).map(d->map("title",d.get("vehicle"),"detail",d.get("expiryDate"),"path","/transport/vehicles/"+d.get("vehicleId"))).toList()),map("title","Open critical faults","items",faults.stream().filter(f->"CRITICAL".equals(f.get("severity"))&&!Set.of("CLOSED","REJECTED").contains(f.get("status"))).map(f->map("title",f.get("reference")+" — "+f.get("vehicle"),"detail",f.get("description"),"path","/transport/faults?record="+f.get("id"))).toList()),map("title","Pending procurement approvals","items",purchases.stream().filter(p->"PENDING_APPROVAL".equals(p.get("status"))).map(p->map("title",p.get("reference")+" — "+p.get("vehicle"),"detail",p.get("justification"),"path","/transport/procurement?record="+p.get("id"))).toList()),map("title","Recent driver submissions","items",faults.stream().filter(f->driverProfiles.findByAccount_Id((Long)f.get("reporterId")).isPresent()).limit(10).map(f->map("title",f.get("reporter")+" — "+f.get("vehicle"),"detail",f.get("description"),"path","/transport/faults?record="+f.get("id"))).toList()));
  return map("metrics",metrics,"monthly",monthly,"availability",distribution(availability),"maintenanceTypes",distribution(maintenanceTypes),"maintenanceStates",distribution(maintenanceStates),"forecast",components.stream().map(c->map("component",c.get("vehicle")+" — "+c.get("name"),"remainingKm",forecast(c).get("remainingKm"),"predictedDate",forecast(c).get("predictedServiceDate"),"status",forecast(c).get("status"),"explanation",forecast(c).get("explanation"))).toList(),"panels",panels,"month",month.toString(),"scope","Values reflect the records accessible to your account. Missing mileage stays unrecorded. Costs are in GHS; procurement receipts are shown separately and may also be included in completed maintenance costs.");
 }
 @SuppressWarnings("unchecked") private Map<String,Object> forecast(Map<String,Object> c){return (Map<String,Object>)c.get("forecast");}
 private Map<String,Object> metric(String label,Object value,String path){return map("label",label,"value",value,"path",path,"currency",false);}
 private Map<String,Object> moneyMetric(String label,Object value,String path){return map("label",label,"value",value,"path",path,"currency",true);}
 private List<Map<String,Object>> distribution(Map<String,Long> values){return values.entrySet().stream().map(e->map("name",e.getKey(),"value",e.getValue())).toList();}
}
